var a=[{title:`Come funziona la resistenza`,text:`Un manubrio pesa lo stesso in ogni punto, ma la resistenza di un elastico dipende da quanto è allungato, da quanto è spesso e da quale prodotto è. Un elastico più lungo o più spesso non equivale a un peso fisso, e i codici colore differiscono tra i produttori. Anche il punto del movimento in cui la resistenza è massima può essere diverso da un esercizio con pesi liberi.`},{title:`Opzioni di esercizi`,text:`Gli elastici funzionano bene per rematori, distensioni, alzate laterali, Pallof press e lat machine da un ancoraggio installato correttamente. Un elastico ad anello attorno alle ginocchia aggiunge una leggera resistenza agli esercizi per i fianchi. Per alcuni movimenti puoi stare in piedi sull’elastico come semplice ancoraggio, purché non possa scivolare e scattare verso l’alto.`},{title:`Ispeziona e ancora in sicurezza`,text:`Prima di ogni sessione, controlla la presenza di crepe, punti sottili, strappi, maniglie danneggiate e connettori consumati. Usa un ancoraggio costruito allo scopo, come indica il produttore, e assicurati che non possa staccarsi. Non allungare troppo l’elastico, non lasciare che sfreghi su bordi taglienti e non mettere il viso lungo il percorso in cui scatterebbe indietro. Un elastico che scivola può causare lesioni agli occhi e altri danni.`},{title:`Progressione e monitoraggio`,text:`Aggiungi ripetizioni controllate, passa a un elastico con più resistenza o cambia la posizione o la distanza dall’ancoraggio, purché il nuovo assetto resti sicuro. La tensione cambia con la lunghezza, quindi annota l’elastico o l’assetto che hai usato; il suo colore non ti darà un peso preciso in chilogrammi. Non aumentare bruscamente allo stesso tempo tensione dell’elastico e range.`},{title:`Usare TrainUp`,text:`In Profilo, inserisci la resistenza degli elastici che hai. Conta i tuoi elastici come disponibili solo quando hai un ancoraggio sicuro per l’esercizio che prevedi di fare. Se non puoi confermare l’ancoraggio, le condizioni dell’elastico o il tuo spazio, scegli un’alternativa più sicura.`}];var o=[{label:`NHS: sicurezza degli elastici di resistenza`,url:`https://abuhb.nhs.wales/files/patient-information-leaflets1/physiotherapy/safety-advice-when-exercising-with-resistance-bands-or-tubing-piu1332/`},{label:`Libreria di esercizi ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Position stand ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var n={sections:a,sources:o};export{n as default,a as sections,o as sources};